def checked_solve(A, b):
    n = A.shape[0]
    if n == 0:
        return cp.zeros_like(b)
    lu, piv = lu_factor(A)
    d = cp.abs(cp.diagonal(lu))
    tol = n * np.finfo(np.float64).eps * cp.max(cp.abs(A))
