import cupyx.scipy.sparse as sp
from cupyx.scipy.sparse.linalg import eigsh


def smallest_eigenvalues(nx, ny, k):
    def T(n):
        return sp.diags([-cp.ones(n - 1), 2 * cp.ones(n), -cp.ones(n - 1)],
                        [-1, 0, 1], shape=(n, n), format="csr", dtype=cp.float64)

    A = (sp.kron(sp.identity(ny, dtype=cp.float64, format="csr"), T(nx)) +
         sp.kron(T(ny), sp.identity(nx, dtype=cp.float64, format="csr"))).tocsr()
    n = nx * ny
    if k >= n - 1 or n < 50:
        w = cp.linalg.eigvalsh(A.toarray())
        return w[:k].astype(cp.float64)
    ncv = min(n - 1, max(4 * k, 40))
    w = eigsh(A, k=k, which="SA", ncv=ncv, maxiter=20 * n, tol=1e-10,
              return_eigenvectors=False)
    return cp.sort(w).astype(cp.float64)

